('01M4D6CBKR18TZNZSXTBTMERN3', '01M4D6CBJZY4V5AYQADTBERA5G', '01M4D6CAZ8NNQKT8CSG8VFTF41', 'council', 0, '01M4D6BHEQ32QCSD0FWQPS6A3W', '2026-10-08T07:24:26.616Z'),
('01M4D6DC13RQ0FWMKC4VZW1P3K', '01M4D6DC12577VFKBG6A0WFTZ8', '01M4D6BHKA2PN56NN1E3X2X84X', 'nes', 1, '01M4D6BHESAT2927NTCFKEXNY5', '2026-10-08T07:24:59.811Z');
INSERT INTO "lessons" ("id", "author_id", "title_en", "title_ar", "context_en", "context_ar", "learning_en", "learning_ar", "recommendation_en", "recommendation_ar", "node_id", "document_ids_json", "classification_level", "status", "reuse_count", "cluster_id", "created_at", "updated_at", "category") VALUES
('01M4D6BHQN82XPN8WTYWZ1853Q', '01M4D6BHEP9TW2034D56782GZ9', 'Test live registers before wiring a data exchange', 'اختبر السجلات الفعلية قبل ربط تبادل البيانات', 'When the regulator data exchange was prepared, two registers used different formats for the same facility identifier, which only surfaced in the first test batch.', 'عند إعداد تبادل البيانات بين الجهات التنظيمية، استخدم سجلان صيغتين مختلفتين لمعرّف المنشأة نفسه، ولم يظهر ذلك إلا في أول دفعة اختبار.', 'Format differences are invisible until real data is tested; a shared field name does not mean a shared format.', 'لا تظهر اختلافات الصيغ حتى تُختبر بيانات فعلية، واسم الحقل المشترك لا يعني صيغة مشتركة.', 'Run a small test with each entity''s live format at least two months before full processing.', 'أجرِ اختباراً صغيراً بصيغة بيانات كل جهة الفعلية قبل شهرين على الأقل من المعالجة الكاملة.', '01M4D6BHKA68MDTK2KKJMDF2GY', NULL, 2, 'published', 5, '01M4D6BRHB6E2JNN6S290QF0M0', '2026-10-06T14:36:00.117Z', '2026-10-08T07:24:26.619Z', 'institutional'),
('01M4D6BHQPNTQ9RD5KK5M2WYKM', '01M4D6BHEPY18BP31WZMBVQ2DJ', 'Flag data quality concerns with source entities early', 'أبلغ الجهات المصدرية مبكراً عن ملاحظات جودة البيانات', 'Quality issues in monitoring data were raised only at the reporting stage, which delayed the release.', 'أُثيرت ملاحظات الجودة في بيانات الرصد عند مرحلة الإبلاغ فقط، مما أخر الإصدار.', 'Early feedback to data owners costs less than late correction.', 'التغذية الراجعة المبكرة لأصحاب البيانات أقل كلفة من التصحيح المتأخر.', 'Share quality findings with the source entity within the same week they are found.', 'شارك ملاحظات الجودة مع الجهة المصدرية خلال الأسبوع نفسه الذي تُكتشف فيه.', '01M4D6BHKA9VZZFR19BVKVN2M6', NULL, 2, 'published', 0, '01M4D6BRHB6E2JNN6S290QF0M0', '2026-10-04T21:48:00.118Z', '2026-10-08T07:24:26.619Z', 'institutional'),
('01M4D6BHQP6FW3M18PZBPXAEB1', '01M4D6BGHAKBD28V6BPQ7S7XE3', 'Pilot a new indicator on a subset of entities first', 'جرّب المؤشر الجديد على مجموعة من الجهات أولاً', 'A new compliance indicator was rolled out to all regulators at once and definitions diverged.', 'طُرح مؤشر امتثال جديد على جميع الجهات التنظيمية دفعة واحدة فتباينت التعريفات.', 'A small pilot reveals definition gaps before they spread.', 'يكشف التطبيق التجريبي الصغير فجوات التعريف قبل انتشارها.', 'Pilot new indicators with two or three entities and fix the definition before scaling.', 'جرّب المؤشرات الجديدة مع جهتين أو ثلاث وأصلح التعريف قبل التوسع.', '01M4D6BHKA767V489TBB9382S1', NULL, 1, 'published', 2, '01M4D6BRHB6E2JNN6S290QF0M0', '2026-10-03T05:00:00.118Z', '2026-10-08T07:24:26.619Z', 'institutional'),
('01M4D6BHQPJ17BARSK0K6YB2MV', '01M4D6BHEP9TW2034D56782GZ9', 'Plan for source platform changes mid-project', 'خطط لتغييرات منصات الجهات المصدرية أثناء المشروع', 'A source entity changed its reporting platform during delivery and the feed broke for three weeks.', 'غيرت جهة مصدرية منصة الإبلاغ أثناء التنفيذ وانقطعت التغذية ثلاثة أسابيع.', 'Dependencies on external platforms need a change notice agreement.', 'الاعتماد على منصات خارجية يتطلب اتفاقاً على الإشعار بالتغيير.', 'Include a change notification clause in every data feed agreement.', 'أدرج بند الإشعار بالتغيير في كل اتفاقية لتغذية البيانات.', '01M4D6BHKB0N8QS15306GNJJHT', NULL, 1, 'verified', 5, '01M4D6BRHGE313M4GBCJ3SVP61', '2026-10-01T12:12:00.118Z', '2026-10-08T07:24:26.619Z', 'delivery'),
('01M4D6BHQQ853170ETK0YY0PKB', '01M4D6BHEV9G5W4Q3XS5WPTZNG', 'Secure control ownership sign-off before publishing standards', 'احصل على موافقة مالكي الضوابط قبل نشر المعايير', 'A data standard was published before the owning entity confirmed it, and was later withdrawn.', 'نُشر معيار بيانات قبل أن تؤكده الجهة المالكة ثم سُحب لاحقاً.', 'Publication without owner sign-off creates rework and loses trust.', 'النشر دون موافقة المالك يخلق إعادة عمل ويفقد الثقة.', 'Record owner sign-off in the registry before any publication.', 'سجّل موافقة المالك في السجل قبل أي نشر.', NULL, NULL, 1, 'published', 1, '01M4D6BRHDV0PTX4W65EER1ZAX', '2026-09-29T19:24:00.119Z', '2026-10-08T07:24:26.619Z', 'delivery'),
('01M4D6BHQQ83999JTWF1WA4P72', '01M4D6BGHA1ANAZV0TK6CR8SAW', 'Invest in change management ahead of the permitting platform', 'استثمر في إدارة التغيير قبل منصة التراخيص', 'The first release of the permitting platform met resistance because inspectors were not briefed.', 'واجه الإصدار الأول لمنصة التراخيص مقاومة لأن المفتشين لم يُطلعوا مسبقاً.', 'Adoption follows communication, not the other way round.', 'يأتي التبني بعد التواصل وليس قبله.', 'Brief users in their own language six weeks before launch and offer short practice sessions.', 'أطلع المستخدمين بلغتهم قبل ستة أسابيع من الإطلاق وقدّم جلسات تدريب قصيرة.', NULL, NULL, 1, 'published', 1, '01M4D6BRHERNG30P0969FMYH64', '2026-09-28T02:36:00.119Z', '2026-10-08T07:24:26.619Z', 'delivery'),
('01M4D6BHQR5RAARQC5ET838DMR', '01M4D6BHEV9G5W4Q3XS5WPTZNG', 'Sequence control implementation to avoid overload', 'رتّب تطبيق الضوابط لتجنب الإرهاق', 'Delivery teams were asked to implement many data controls in the same quarter.', 'طُلب من فرق التنفيذ تطبيق ضوابط بيانات كثيرة في الربع نفسه.', 'Too many simultaneous requirements reduce quality.', 'كثرة المتطلبات المتزامنة تقلل الجودة.', 'Stage controls by priority across several quarters.', 'وزّع الضوابط بحسب الأولوية على عدة أرباع.', '01M4D6BHKA5J0C6W1G72EMTVM0', NULL, 1, 'published', 3, '01M4D6BRHCTTQ22NQ6FSB7G4HT', '2026-09-26T09:48:00.120Z', '2026-10-08T07:24:26.620Z', 'delivery'),
('01M4D6BHQR6AVKYTRRA28PF9PT', '01M4D6BHEVMQK6SR4J1Y8T08WK', 'Build an exception process before mandating full compliance', 'ابنِ مسار استثناءات قبل إلزام الامتثال الكامل', 'A new reporting rule left no route for entities with legitimate constraints.', 'ترك نظام إبلاغ جديد دون مسار للجهات ذات القيود المشروعة.', 'Mandates without exceptions get ignored or escalated.', 'الإلزام دون استثناءات يُتجاهل أو يُصعَّد.', 'Define a short exception request with time limits.', 'حدد طلب استثناء مختصراً بمهلة زمنية.', '01M4D6BHKB55AMTE7TTJ0BSXS9', NULL, 1, 'verified', 1, '01M4D6BRHDAFCW00AZ7YVK9VRW', '2026-09-24T17:00:00.120Z', '2026-10-08T07:24:26.620Z', 'delivery'),
('01M4D6BHQR1JYWGF2MR132SP0Q', '01M4D6BHETEQ14RFJ4M9ZHBW8N', 'Anchor delivery workshops around entity budgets and calendars', 'اجعل ورش التنفيذ مرتبطة بميزانيات الجهات وتقاويمها', 'Workshops scheduled outside entity planning windows had low attendance.', 'انخفض الحضور في ورش عُقدت خارج فترات تخطيط الجهات.', 'Timing matters as much as content.', 'التوقيت لا يقل أهمية عن المحتوى.', 'Schedule workshops around each entity''s planning calendar.', 'جدول الورش بحسب تقويم إعداد الخطط لكل جهة.', '01M4D6BHKAHVZ9PQPPGR6BPJ3E', NULL, 1, 'published', 1, '01M4D6BRHFH2XV9Q464PNYTRAD', '2026-09-23T00:12:00.120Z', '2026-10-08T07:24:26.620Z', 'delivery'),
('01M4D6BHQSTSJPWXQTVYW0308V', '01M4D6BHETF9W8SQHJXQS8JBQT', 'Share a common glossary before cross-theme KPI work', 'شارك مسرداً مشتركاً قبل العمل على مؤشرات عابرة للمحاور', 'Themes used different meanings for reuse, recovery and diversion.', 'استخدمت المحاور معاني مختلفة لإعادة الاستخدام والاسترداد والتحويل.', 'Shared terms avoid weeks of argument over numbers.', 'المصطلحات المشتركة تجنّب أسابيع من الجدل حول الأرقام.', 'Agree a glossary before any cross-theme KPI session.', 'اتفق على مسرد قبل أي جلسة مؤشرات عابرة للمحاور.', '01M4D6BHKA8MZYDMEVAAWDASDP', NULL, 1, 'published', 5, NULL, '2026-09-21T07:24:00.121Z', '2026-10-08T07:24:26.620Z', 'delivery'),
('01M4D6BHQTSFJ5VRF3A3NVJ3FM', '01M4D6BHETEQ14RFJ4M9ZHBW8N', 'Document workshop outcomes immediately', 'وثّق مخرجات الورش فور انتهائها', 'Decisions from a delivery workshop were reconstructed from memory two weeks later.', 'أُعيد بناء قرارات ورشة تنفيذ من الذاكرة بعد أسبوعين.', 'Decisions fade fast.', 'القرارات تُنسى بسرعة.', 'Circulate a decision log within 24 hours.', 'عمّم سجل القرارات خلال 24 ساعة.', '01M4D6BHKA2PN56NN1E3X2X84X', NULL, 1, 'published', 1, '01M4D6BRHGE313M4GBCJ3SVP61', '2026-09-19T14:36:00.122Z', '2026-10-08T07:24:26.620Z', 'delivery'),
('01M4D6BHQVHF83S3H5WT3ESCBR', '01M4D6BHF37BQ4PDMG2KHFXHXX', 'Pilot the scorecard with one champion team before launch', 'جرّب بطاقة المؤشرات مع فريق رائد قبل الإطلاق', 'The scorecard was shown to all teams at once and feedback was scattered.', 'عُرضت بطاقة المؤشرات على جميع الفرق دفعة واحدة وتشتتت الملاحظات.', 'A champion team gives focused feedback.', 'يقدم الفريق الرائد ملاحظات مركزة.', 'Pilot with one team for a month, then expand.', 'جرّب مع فريق واحد لمدة شهر ثم وسّع.', '01M4D6BHKBF9AFJ09F8RS7DCP7', NULL, 1, 'published', 4, '01M4D6BRHDV0PTX4W65EER1ZAX', '2026-09-17T21:48:00.123Z', '2026-10-08T07:24:26.620Z', 'delivery'),
('01M4D6BHQVFZEC2HFF6RXJVN9N', '01M4D6BHENXFYQ2E4HXXWJ52XS', 'Standardise indicator naming conventions', 'وحّد قواعد تسمية المؤشرات', 'Similar indicators carried different names across themes, which confused search.', 'حملت مؤشرات متشابهة أسماء مختلفة عبر المحاور مما أربك البحث.', 'Naming conventions are cheap and valuable.', 'قواعد التسمية قليلة الكلفة وكبيرة الفائدة.', 'Publish a naming guide and apply it in the registry.', 'انشر دليل تسمية وطبقه في السجل.', '01M4D6BHKBQP5D9N5WCE4F2ZEM', NULL, 1, 'verified', 6, '01M4D6BRHERNG30P0969FMYH64', '2026-09-16T05:00:00.123Z', '2026-10-08T07:24:26.620Z', 'delivery'),
('01M4D6BHQV0T5DX85VVVVRNRRC', '01M4D6BHEVS1JTE18GWSJCMM5R', 'Budget time for metadata migration from legacy files', 'خصص وقتاً لترحيل البيانات الوصفية من الملفات القديمة', 'Moving legacy documents into the knowledge system took longer than planned because metadata was missing.', 'استغرق نقل الوثائق القديمة إلى منظومة المعرفة وقتاً أطول من المخطط بسبب نقص البيانات الوصفية.', 'Missing metadata is the main migration cost.', 'نقص البيانات الوصفية هو الكلفة الرئيسية للترحيل.', 'Estimate effort per document and tag in batches.', 'قدّر الجهد لكل وثيقة ووسّم على دفعات.', '01M4D6BHKA767V489TBB9382S1', NULL, 1, 'published', 5, '01M4D6BRHCTTQ22NQ6FSB7G4HT', '2026-09-14T12:12:00.123Z', '2026-10-08T07:24:26.620Z', 'delivery'),
('01M4D6BHQWCP8735V7E65HB2QC', '01M4D6BHEVS1JTE18GWSJCMM5R', 'Bilingual dataset descriptions raise reuse', 'الأوصاف ثنائية اللغة ترفع إعادة الاستخدام', 'Datasets with Arabic and English descriptions were reused more often.', 'استُخدمت مجموعات البيانات ذات الأوصاف العربية والإنجليزية أكثر من غيرها.', 'Language access drives reuse.', 'إتاحة اللغة تدفع إعادة الاستخدام.', 'Publish both languages together.', 'انشر اللغتين معاً.', NULL, NULL, 1, 'verified', 1, '01M4D6BRHDAFCW00AZ7YVK9VRW', '2026-09-12T19:24:00.124Z', '2026-10-08T07:24:26.621Z', 'delivery'),
('01M4D6BHQWB3QRJ4C1S6RVGM82', '01M4D6BHF3952678NKGW8E66VY', 'Assign a single point of contact per international index', 'عيّن جهة اتصال واحدة لكل مؤشر دولي', 'Several teams answered the same index questionnaire differently.', 'أجابت عدة فرق عن استبيان المؤشر نفسه بإجابات مختلفة.', 'One owner per index keeps answers consistent.', 'وجود مالك واحد لكل مؤشر يحافظ على اتساق الإجابات.', 'Name a focal point per index.', 'سمِّ منسقاً لكل مؤشر.', '01M4D6BHKAZN0S0RP7WPH3GCM2', NULL, 1, 'published', 6, '01M4D6BRHFH2XV9Q464PNYTRAD', '2026-09-11T02:36:00.124Z', '2026-10-08T07:24:26.621Z', 'delivery'),
('01M4D6BHQWYQ2JXRJ3C7RHMNXS', '01M4D6BHF3952678NKGW8E66VY', 'Attend a study visit with a defined learning question', 'شارك في زيارة دراسية بسؤال تعلم محدد', 'After a study visit to a regional water authority, teams returned with general notes only.', 'بعد زيارة دراسية إلى جهة مياه إقليمية، عاد الفرق بملاحظات عامة فقط.', 'Study visits work when each participant owns one learning question.', 'تنجح الزيارات الدراسية حين يتولى كل مشارك سؤال تعلم واحداً.', 'Assign a question to each participant before the visit and report back in a one-page note.', 'كلّف كل مشارك بسؤال قبل الزيارة وأعد تقريراً من صفحة واحدة.', '01M4D6BHKB6G701EQW5T6E6Z04', NULL, 1, 'published', 2, '01M4D6BRHB6E2JNN6S290QF0M0', '2026-09-09T09:48:00.124Z', '2026-10-08T07:24:26.621Z', 'external'),
('01M4D6BHQXVXE94C6PVAXDSRZX', '01M4D6BHF3952678NKGW8E66VY', 'Benchmark indicators against peers before setting a target', 'قارن المؤشرات بنظيراتها قبل وضع المستهدف', 'A target was set without checking how peer countries define and measure the indicator.', 'وُضع مستهدف دون التحقق من كيفية تعريف الدول النظيرة للمؤشر وقياسه.', 'Benchmarking prevents unrealistic or incomparable targets.', 'المقارنة المرجعية تمنع المستهدفات غير الواقعية أو غير القابلة للمقارنة.', 'Run a short benchmark of definitions and levels before approving a target.', 'أجرِ مقارنة قصيرة للتعريفات والمستويات قبل اعتماد المستهدف.', '01M4D6BHKBYEX0MGWHRXS7GA76', NULL, 1, 'verified', 0, '01M4D6BRHB6E2JNN6S290QF0M0', '2026-09-07T17:00:00.125Z', '2026-10-08T07:24:26.621Z', 'external'),
('01M4D6BHQXFY3S17X3VW49JS0G', '01M4D6BGHA1ANAZV0TK6CR8SAW', 'Capture lessons at the Saudi Green Initiative Forum within a week', 'وثّق دروس منتدى مبادرة السعودية الخضراء خلال أسبوع', 'Insights from forum sessions were not written down and were lost.', 'لم تُدوّن رؤى جلسات المنتدى فضاعت.', 'A short debrief preserves what attendees heard.', 'جلسة تلخيص قصيرة تحفظ ما سمعه الحضور.', 'Hold a debrief and file a note in the library within a week.', 'اعقد جلسة تلخيص وأودع مذكرة في المكتبة خلال أسبوع.', '01M4D6BHKB9EA0A8ETCJJBHTXV', NULL, 1, 'published', 3, '01M4D6BRHB6E2JNN6S290QF0M0', '2026-09-06T00:12:00.125Z', '2026-10-08T07:24:26.621Z', 'external'),
('01M4D6BHQX5DBD96QYQS9XYMMF', '01M4D6BGHA1ANAZV0TK6CR8SAW', 'Interview departing experts before handover', 'قابل الخبراء المغادرين قبل التسليم', 'A senior analyst left and the logic behind several indicator adjustments was lost.', 'غادر محلل أول وضاع منطق عدة تعديلات على المؤشرات.', 'Tacit knowledge lives in people; an expert interview captures it.', 'المعرفة الضمنية تكمن في الأشخاص، والمقابلة مع الخبير تحفظها.', 'Schedule a structured interview and record the answers in the library.', 'حدد مقابلة منظمة وسجّل الإجابات في المكتبة.', '01M4D6BHKA5GFF7WPA08B5J7SG', NULL, 1, 'verified', 5, '01M4D6BRHB6E2JNN6S290QF0M0', '2026-09-04T07:24:00.125Z', '2026-10-08T07:24:26.621Z', 'expert'),
('01M4D6BHQX3WP7AFG3H66XZTZQ', '01M4D6BHETEQ14RFJ4M9ZHBW8N', 'Pair new analysts with a mentor for their first indicator review', 'اربط المحللين الجدد بمرشد في أول مراجعة للمؤشرات', 'New analysts took longer to learn the review process without a mentor.', 'احتاج المحللون الجدد إلى وقت أطول لتعلم المراجعة دون مرشد.', 'Mentoring shortens the learning curve.', 'الإرشاد يقصّر منحنى التعلم.', 'Assign a mentor for the first two reviews.', 'عيّن مرشداً لأول مراجعتين.', '01M4D6BHKBWQ3XVJXK95NFPTCX', NULL, 1, 'published', 4, '01M4D6BRHCTTQ22NQ6FSB7G4HT', '2026-09-02T14:36:00.125Z', '2026-10-08T07:24:26.621Z', 'delivery'),
('01M4D6BHQYJZKS80308C8N4B8C', '01M4D6BGHA1ANAZV0TK6CR8SAW', 'Short recurring knowledge sessions build habits', 'الجلسات المعرفية القصيرة المتكررة تبني العادات', 'Monthly long sessions had low turnout; weekly short ones did better.', 'انخفض الحضور في الجلسات الشهرية الطويلة وتحسّن في الجلسات الأسبوعية القصيرة.', 'Frequency beats duration.', 'التكرار أهم من المدة.', 'Run 20-minute sessions weekly.', 'نظّم جلسات من 20 دقيقة أسبوعياً.', '01M4D6BHKAYFRDMQA7VE4A7Q9E', NULL, 1, 'published', 2, '01M4D6BRHDAFCW00AZ7YVK9VRW', '2026-08-31T21:48:00.126Z', '2026-10-08T07:24:26.622Z', 'delivery'),
('01M4D6CBJXKHJMGGXXNE6P7EZN', '01M4D6BHF72K33W57W4DV15TTK', 'Agree the data definition before the dashboard is built', 'الاتفاق على تعريف البيانات قبل بناء لوحة المتابعة', 'Two units reported the same measure differently for a full quarter because the definition lived in a slide, not in a card.', 'أبلغت وحدتان عن المقياس نفسه بطريقتين مختلفتين لربع كامل لأن التعريف كان في عرض تقديمي لا في بطاقة مؤشر.', 'A dashboard hardens whatever definition it is given. Write the indicator card first, have the owning unit sign it, then build.', 'تثبت لوحة المتابعة أي تعريف يعطى لها. اكتب بطاقة المؤشر أولاً واعتمدها من الوحدة المالكة ثم ابنِ.', 'No dashboard build starts without an approved indicator card for every figure on it.', 'لا يبدأ بناء أي لوحة متابعة دون بطاقة مؤشر معتمدة لكل رقم عليها.', NULL, NULL, 2, 'verified', 3, NULL, '2026-01-05T00:00:00.000Z', '2026-10-08T07:24:26.622Z', 'delivery'),
('01M4D6CBJXGKZ0NYZBJGV0EB2K', '01M4D6BHF5XQA06C5Z707P3NMH', 'Entity planning teams need the template and a worked example', 'فرق التخطيط في الجهات تحتاج النموذج ومثالاً مطبقاً', 'The first round of submissions using the new template came back with the results chain filled in as a list of activities.', 'عادت الجولة الأولى من الطلبات بالنموذج الجديد وسلسلة النتائج مملوءة بقائمة أنشطة.', 'A template teaches format, not thinking. A completed example from a real sector teaches both.', 'يعلّم النموذج الشكل لا التفكير. المثال المكتمل من قطاع حقيقي يعلّم الاثنين.', 'Ship every planning template with one fully worked example and a thirty minute clinic.', 'أرفق مع كل نموذج تخطيط مثالاً مكتملاً وجلسة إرشادية مدتها ثلاثون دقيقة.', NULL, NULL, 2, 'published', 3, NULL, '2026-02-06T00:00:00.000Z', '2026-10-08T07:24:26.622Z', 'delivery'),
('01M4D6CBJY10PWD9J5AZT2DX92', '01M4D6BHF843YQERMTDQX9X22N', 'Publish the revision policy before the first revision', 'انشر سياسة المراجعة قبل أول مراجعة', 'A routine revision to a quarterly figure was read as an error because no published policy explained when revisions happen.', 'فُهمت مراجعة روتينية لرقم ربع سنوي على أنها خطأ لعدم وجود سياسة منشورة توضح متى تجري المراجعات.', 'Trust is lost at the first unexplained change, not at the tenth.', 'تُفقد الثقة عند أول تغيير غير مفسر لا عند العاشر.', 'Publish the revisions policy alongside the release calendar, before any product goes live.', 'انشر سياسة المراجعات مع تقويم الإصدار قبل إطلاق أي منتج.', NULL, NULL, 2, 'published', 1, NULL, '2026-03-07T00:00:00.000Z', '2026-10-08T07:24:26.622Z', 'delivery'),
('01M4D6CBJYX5HZ68GFT2QH540R', '01M4D6BHEVS1JTE18GWSJCMM5R', 'A data sharing agreement moves faster with a named owner on both sides', 'تتحرك اتفاقية تبادل البيانات أسرع بوجود مالك محدد من الطرفين', 'Agreements with a named focal point on each side closed in weeks; those routed through general correspondence took months.', 'أُغلقت الاتفاقيات التي لها منسق محدد من كل طرف خلال أسابيع، بينما استغرقت المرسلة عبر المراسلات العامة شهوراً.', 'The bottleneck is rarely legal. It is the absence of a person whose job it is to close the file.', 'نادراً ما يكون العائق قانونياً، بل غياب شخص مهمته إغلاق الملف.', 'Name a focal point on both sides in the first meeting and record it in the file.', 'حدد منسقاً من الطرفين في الاجتماع الأول وسجله في الملف.', NULL, NULL, 2, 'verified', 4, NULL, '2026-04-08T00:00:00.000Z', '2026-10-08T07:24:26.622Z', 'delivery'),
('01M4D6CBJYTB842T781TSVT1D7', '01M4D6BHEST5ZXVWHEEFMYH70F', 'Scenario work lands when it is tied to a decision on the table', 'تؤتي السيناريوهات ثمارها حين ترتبط بقرار مطروح', 'A well made scenario set was read once and shelved; a smaller one prepared for a budget decision changed the decision.', 'قُرئت مجموعة سيناريوهات متقنة مرة واحدة ثم حُفظت، بينما غيّرت مجموعة أصغر أُعدت لقرار موازنة القرار نفسه.', 'Foresight products compete with the inbox. Anchoring them to a live decision is what gets them read.', 'تنافس منتجات الاستشراف صندوق الوارد. ربطها بقرار قائم هو ما يجعلها تُقرأ.', 'Start every scenario commission by naming the decision it must inform and its date.', 'ابدأ تكليف أي سيناريو بتحديد القرار الذي يجب أن يخدمه وتاريخه.', NULL, NULL, 2, 'published', 4, NULL, '2026-05-09T00:00:00.000Z', '2026-10-08T07:24:26.622Z', 'delivery'),
('01M4D6CBJZ8R2SSSZ4T97FYFVW', '01M4D6BHF37BQ4PDMG2KHFXHXX', 'Automation saves nothing until the paper step is removed', 'لا توفر الأتمتة شيئاً حتى تُلغى الخطوة الورقية', 'A workflow was automated while the signed paper copy stayed mandatory, so the cycle time did not move.', 'أُتمتت دورة عمل مع بقاء النسخة الورقية الموقعة إلزامية فلم يتغير زمن الدورة.', 'Digitising a process next to the old one adds work. The old step has to be retired in the same release.', 'رقمنة إجراء بجانب الإجراء القديم تضيف عملاً. يجب إلغاء الخطوة القديمة في الإصدار نفسه.', 'Every automation change request must name the manual step it removes.', 'يجب أن يحدد كل طلب أتمتة الخطوة اليدوية التي يلغيها.', NULL, NULL, 2, 'published', 1, NULL, '2026-06-10T00:00:00.000Z', '2026-10-08T07:24:26.622Z', 'delivery'),
('01M4D6CBJZY4V5AYQADTBERA5G', '01M4D6BHEQ32QCSD0FWQPS6A3W', 'Quality assurance findings need an owner and a date, not a report', 'تحتاج نتائج ضمان الجودة مالكاً وتاريخاً لا تقريراً', 'The first quality review produced 34 findings; six months later 29 were still open because none carried a name.', 'أنتجت أول مراجعة جودة 34 ملاحظة، وبعد ستة أشهر بقيت 29 مفتوحة لأن أياً منها لم يحمل اسماً.', 'A finding without an owner is an observation. With an owner and a date it becomes work.', 'الملاحظة بلا مالك مجرد رصد. وبمالك وتاريخ تصبح عملاً.', 'Close every quality review by assigning each finding to a person with a due date.', 'اختم كل مراجعة جودة بإسناد كل ملاحظة إلى شخص مع تاريخ استحقاق.', NULL, NULL, 2, 'verified', 0, NULL, '2026-07-11T00:00:00.000Z', '2026-10-08T07:24:26.622Z', 'delivery'),
('01M4D6CBJZAY6WJMCFEJZCW6Z6', '01M4D6BHETF9W8SQHJXQS8JBQT', 'Training uptake follows the manager, not the invitation', 'يتبع الإقبال على التدريب المدير لا الدعوة', 'Units whose head attended the first session reached 80 percent completion; units where the invitation went straight to staff reached 30.', 'بلغت الوحدات التي حضر رئيسها الجلسة الأولى 80 في المئة إتماماً، بينما بلغت الوحدات التي أُرسلت فيها الدعوة للموظفين مباشرة 30 في المئة.', 'Attendance is a signal about priority, and staff read it from their manager.', 'الحضور إشارة عن الأولوية، ويقرأها الموظفون من مديرهم.', 'Book the unit head into the first session of every capability programme.', 'احجز مقعد رئيس الوحدة في الجلسة الأولى من كل برنامج بناء قدرات.', NULL, NULL, 2, 'published', 2, NULL, '2026-08-12T00:00:00.000Z', '2026-10-08T07:24:26.623Z', 'delivery'),
('01M4D6CBK07M7E70A94235PTAJ', '01M4D6BHENSE7ST85QF7RWE08R', 'One catalogue entry is worth ten shared folders', 'مدخل واحد في الفهرس يعادل عشرة مجلدات مشتركة', 'The same dataset existed in four places with three different vintages before the catalogue entry was created.', 'وُجدت مجموعة البيانات نفسها في أربعة أماكن بثلاث نسخ زمنية مختلفة قبل إنشاء مدخل الفهرس.', 'Duplication is a symptom of an absent authoritative record, not of careless staff.', 'التكرار عرض لغياب سجل مرجعي لا لإهمال الموظفين.', 'Create the catalogue entry when the dataset is first produced, not when it is first requested.', 'أنشئ مدخل الفهرس عند إنتاج البيانات أول مرة لا عند طلبها أول مرة.', NULL, NULL, 2, 'published', 2, NULL, '2026-09-13T00:00:00.000Z', '2026-10-08T07:24:26.623Z', 'delivery'),
('01M4D6CBK0KJN807YPDVBEC3SH', '01M4D6BHF7VAJWJZDPEEWSB80N', 'A monthly indicator needs a monthly owner', 'المؤشر الشهري يحتاج مالكاً شهرياً', 'Monthly indicators assigned to a committee were reported late three months in a row; the same indicators assigned to a person were on time.', 'تأخر الإبلاغ عن المؤشرات الشهرية المسندة إلى لجنة ثلاثة أشهر متتالية، بينما التزمت المؤشرات نفسها بالمواعيد حين أُسندت إلى شخص.', 'Reporting cadence has to match the accountability unit. A committee cannot meet monthly about one number.', 'يجب أن تتوافق دورية الإبلاغ مع وحدة المساءلة. لا يمكن للجنة أن تجتمع شهرياً حول رقم واحد.', 'Every monthly indicator card names one responsible person, never a body.', 'تحدد بطاقة كل مؤشر شهري شخصاً مسؤولاً واحداً لا جهة.', NULL, NULL, 2, 'verified', 3, NULL, '2026-01-14T00:00:00.000Z', '2026-10-08T07:24:26.623Z', 'delivery'),
('01M4D6DC12577VFKBG6A0WFTZ8', '01M4D6BHESAT2927NTCFKEXNY5', 'Expert Insights: PRJ-15a Industrial Symbiosis Pilot', 'رؤى الخبراء: PRJ-15a Industrial Symbiosis Pilot', 'Status: The environmental monitoring round for 2026 is 70 percent complete. The next milestone is the quality review on the 15th of next month, and the field teams already have their schedules. Watch out for: The 2024 round slipped because the station register arrived late. Where things live: The working files are in the DOP shared drive under /operations/2026, the final tables in the Vault, and the field logs in the tablet console; the data quality team holds the console admin account.
