INSERT INTO "node_lineage" ("id", "from_node_id", "to_node_id", "relation", "note_en", "note_ar") VALUES
('01M4D6BHNEWW636EPE7114ASFY', '01M4D6BHKCGZYGTWK9ZGWQG2VT', '01M4D6BHKB4HX5ME3PTPVJM3Y1', 'evolved_into', 'Water supply foundations matured into a dedicated sector strategy for water resources and supply.', 'تطورت أسس الإمداد المائي إلى استراتيجية قطاعية مستقلة للموارد المائية والإمداد.'),
('01M4D6BHNF2D62M22JF10RCAJ2', '01M4D6BHKCNK1CMM9W0NVDWBJ5', '01M4D6BHKBGBZXE020Z7A90HRK', 'evolved_into', 'Wastewater foundations became the wastewater and reuse sector strategy.', 'أصبحت أسس مياه الصرف استراتيجية قطاع مياه الصرف وإعادة الاستخدام.'),
('01M4D6BHNFE184R3EP2WZSTENE', '01M4D6BHKCH894V4WP9KF64F2Y', '01M4D6BHKCPMT8438F1ZTBN41A', 'continued', 'Agriculture foundations continued into the agriculture and rural development strategy.', 'استمرت أسس الزراعة ضمن استراتيجية الزراعة والتنمية الريفية.'),
('01M4D6BHNFFG0ETFFVS1ZPN9X5', '01M4D6BHKC1EQ3C6Z10HWVA60P', '01M4D6BHKC2P6BVBB5GRD4HES2', 'evolved_into', 'Wildlife and habitat foundations became the biodiversity and protected areas strategy.', 'أصبحت أسس الحياة الفطرية والموائل استراتيجية التنوع الأحيائي والمحميات.'),
('01M4D6BHNFD227Z2777X99AWRY', '01M4D6BHKCYG6VP3RTJG9XWADC', '01M4D6BHKCZD4M4R761KAN6N49', 'evolved_into', 'Desertification foundations became the desertification and vegetation cover strategy.', 'أصبحت أسس مكافحة التصحر استراتيجية التصحر والغطاء النباتي.'),
('01M4D6BHNFGS8JQCR6MECKZXZ0', '01M4D6BHKCJJN9VN32Y2CYA8Q9', '01M4D6BHKCFAY6T4VWC4KAVWHS', 'continued', 'Waste foundations continued into the waste management sector strategy.', 'استمرت أسس إدارة النفايات ضمن استراتيجية قطاع إدارة النفايات.'),
('01M4D6BHNFY3K9NW1P0KM6T020', '01M4D6BHKCR04S2PQJ5EJXV3NZ', '01M4D6BHKCK5VGXHSNBJKNC728', 'merged_into', 'Meteorology and climate observation merged into climate and energy transition planning.', 'اندمج رصد الأرصاد والمناخ في تخطيط المناخ وتحول الطاقة.'),
('01M4D6BHNFVX6AT367YH99J3EX', '01M4D6BHKCAN95PZAQM18VTB1B', '01M4D6BHKCABBTXH7AQC40RWA5', 'evolved_into', 'Institutional foundations became environmental governance and law.', 'أصبحت الأسس المؤسسية الحوكمة البيئية والنظام.'),
('01M4D6BHNFFQD02VDA5N3NZA07', '01M4D6BHKB4HX5ME3PTPVJM3Y1', '01M4D6BHK9576VE73AKHSCPJCR', 'continued', 'Water resources and supply planning continued into the Water Security theme.', 'استمر تخطيط الموارد المائية والإمداد ضمن محور الأمن المائي.'),
('01M4D6BHNFGZGCWXBM8RKK4K93', '01M4D6BHKBGBZXE020Z7A90HRK', '01M4D6BHK9576VE73AKHSCPJCR', 'merged_into', 'Wastewater and reuse merged into the Water Security theme.', 'اندمج قطاع مياه الصرف وإعادة الاستخدام في محور الأمن المائي.'),
('01M4D6BHNF4NH41P03QBTHG4BT', '01M4D6BHKCPMT8438F1ZTBN41A', '01M4D6BHK9K95DGK4RSBSQKWH0', 'continued', 'Agriculture and rural development continued into Agriculture and Food Security.', 'استمرت الزراعة والتنمية الريفية ضمن محور الأمن الغذائي والزراعة.'),
('01M4D6BHNFK399RJ7AYPSY81EY', '01M4D6BHKCNV9QVZJR57SN4YGP', '01M4D6BHK9K95DGK4RSBSQKWH0', 'merged_into', 'Food security merged into the Agriculture and Food Security theme.', 'اندمج الأمن الغذائي في محور الأمن الغذائي والزراعة.'),
('01M4D6BHNG2ADC597PZZJ9J4S6', '01M4D6BHKC2P6BVBB5GRD4HES2', '01M4D6BHK985WAR19CDE822C55', 'continued', 'Biodiversity and protected areas continued into Biodiversity and Land.', 'استمر التنوع الأحيائي والمحميات ضمن محور التنوع الأحيائي والأراضي.'),
('01M4D6BHNGYYH9ZR24E6ZV7M1M', '01M4D6BHKCZD4M4R761KAN6N49', '01M4D6BHK985WAR19CDE822C55', 'merged_into', 'Desertification and vegetation cover merged into Biodiversity and Land.', 'اندمج التصحر والغطاء النباتي في محور التنوع الأحيائي والأراضي.'),
('01M4D6BHNG8HR7DNXYBMFNSBEQ', '01M4D6BHKCFAY6T4VWC4KAVWHS', '01M4D6BHK9ZC3FQM79EBENHZZS', 'evolved_into', 'Waste management evolved into the Waste and Circular Economy theme.', 'تطورت إدارة النفايات إلى محور النفايات والاقتصاد الدائري.'),
('01M4D6BHNG763G53RE5J9N88QX', '01M4D6BHKCQRAQ8H38PQS34WVJ', '01M4D6BHK98RDWCXHQPEBWMYRK', 'evolved_into', 'Air quality and pollution control evolved into the Air Quality theme.', 'تطور قطاع جودة الهواء ومكافحة التلوث إلى محور جودة الهواء.'),
('01M4D6BHNGWNRMFDQ8M8C7XFMD', '01M4D6BHKCK5VGXHSNBJKNC728', '01M4D6BHK9906RXCKJDEFHHBAC', 'continued', 'Climate and energy transition continued into the Climate and Environment theme.', 'استمر المناخ وتحول الطاقة ضمن محور المناخ والبيئة.'),
('01M4D6BHNGSP5VRCR8GTM98KCE', '01M4D6BHKCABBTXH7AQC40RWA5', '01M4D6BHK9NM2DQJ5JEAEJ758J', 'evolved_into', 'Environmental governance and law evolved into Regulatory Compliance and Enforcement.', 'تطورت الحوكمة البيئية والنظام إلى محور الامتثال التنظيمي والإنفاذ.'),
('01M4D6BHNGDXFQ2V900HXDZKEE', '01M4D6BHKCABH0BJ0RYFRBB77V', '01M4D6BHK9EB0VGP6S0GNSZWAM', 'evolved_into', 'Environmental data and research evolved into the data and monitoring enabler.', 'تطورت البيانات والأبحاث البيئية إلى ممكّن البيانات والرصد.'),
