INSERT INTO "operating_principles" ("id", "sort", "title_en", "title_ar", "text_en", "text_ar", "is_illustrative") VALUES
('01M4D6DDB685ZG7KD6F3DCYX9E', 0, 'Evidence-based planning', 'التخطيط المستند إلى الأدلة', 'Every environmental plan, target and policy recommendation rests on data whose source is named and a method that can be explained; where the evidence is thin the plan says so.', 'تستند كل خطة بيئية ومستهدف وتوصية سياساتية إلى بيانات محددة المصدر ومنهجية قابلة للشرح، وحين تكون الأدلة محدودة تُصرّح الخطة بذلك.', 1),
('01M4D6DDB6A1YF7V5BX8VZ68RD', 1, 'One trusted data source', 'مصدر موثوق واحد للبيانات', 'Environmental data is produced once, to one standard, and reused by every entity; no figure reaches a decision through a parallel channel.', 'تُنتج البيانات البيئية مرة واحدة وفق معيار واحد وتُعاد الاستفادة منها في كل جهة، ولا يصل أي رقم إلى قرار عبر قناة موازية.', 1),
('01M4D6DDB7HB9TSJM57ZZ8EAWV', 2, 'Results orientation', 'التوجه نحو النتائج', 'Work is planned, budgeted and reported as a results chain from inputs to themes, and progress is judged by what changed for the Kingdom, not by activity counts.', 'يُخطط العمل ويُموَّل ويُرفع عنه التقرير بوصفه سلسلة نتائج من المدخلات إلى المحاور، ويُقاس التقدم بما تغير للمملكة لا بعدد الأنشطة.', 1),
('01M4D6DDB7SS9MKD7S7ANCP94V', 3, 'Partnership with entities', 'الشراكة مع الجهات', 'Government entities are partners in delivery, not recipients of instructions; every interface with an entity has a named focal point on both sides and an agreed cadence.', 'الجهات الحكومية شريكة في التنفيذ لا متلقية للتعليمات، ولكل واجهة تعامل مع جهة منسق مسمّى من الطرفين ودورية متفق عليها.', 1),
('01M4D6DDB7Z4HQZYWD3BHBMG4E', 4, 'Foresight before planning', 'الاستشراف قبل التخطيط', 'Signals, scenarios and risks feed every planning cycle at its start, so that plans prepare for what is likely and for what is merely possible.', 'تغذي الإشارات والسيناريوهات والمخاطر كل دورة تخطيط في بدايتها، لتستعد الخطط لما هو مرجّح ولما هو ممكن فحسب.', 1),
('01M4D6DDB8QM18W5SS7Z7VYQRS', 5, 'Institutional learning', 'التعلم المؤسسي', 'Every process closes with a lesson recorded where the next team will find it, and every departure hands knowledge over deliberately so the Office never loses a capability with a person.', 'تُختتم كل عملية بدرس يُدوَّن حيث يجده الفريق التالي، ويُسلَّم كل مغادر معرفته بشكل منظم حتى لا يفقد المكتب قدرة برحيل شخص.', 1);
