INSERT INTO "org_snapshots" ("id", "taken_at", "taken_by", "tree_json", "note") VALUES
('01M4D6CBPBNTXGYV2D3SR3T7EP', '2026-10-08T07:24:26.699Z', NULL, '{"version":1,"units":[{"id":"01M4D6BGEN9QDGX3095WSWMVDJ","code":"OPD","nameEn":"Office of the Programme Director","nameAr":"مكتب مدير البرنامج","level":"office","parentId":null,"sort":1,"isActive":1,"headUserId":"01M4D6BHF6S74N94EN6YKC3CPH","headNameEn":"Faisal Al-Harbi","headNameAr":"فيصل الحربي","headTitleEn":"Head of Office","headTitleAr":"رئيس المكتب","mandateEn":"Leads the Office, chairs its executive committee and answers to the Programme Steering Committee for delivery of the National Environment Strategy. Sets priorities across sectors and represents the Office with national entities.","mandateAr":"يقود المكتب ويرأس لجنته التنفيذية ويرفع إلى اللجنة التوجيهية للبرنامج عن تنفيذ الاستراتيجية الوطنية للبيئة. يحدد الأولويات بين القطاعات ويمثل المكتب لدى الجهات الوطنية.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":"Supports the Programme Director: steering committee coordination, entity relations, and the Office''s decision pipeline.","responsibilitiesAr":"يساند مدير البرنامج: التنسيق مع اللجنة التوجيهية وعلاقات الجهات وخط قرارات المكتب.","descriptionEn":"The Office of the Programme Director provides executive support to the Programme Director, runs communications and legal advice for the Programme Office, and coordinates relations with MEWA and the delivery entities.","descriptionAr":"يقدم مكتب مدير البرنامج الدعم التنفيذي لمدير البرنامج، ويتولى الاتصال المؤسسي والمشورة القانونية لمكتب البرنامج، وينسق العلاقة مع وزارة البيئة والمياه والزراعة والجهات المنفذة.","keyProjectsNote":null},{"id":"01M4D6CAGXNZAHAF8RXASHE207","code":"SPS","nameEn":"Strategy and Performance Sector","nameAr":"قطاع الاستراتيجية والأداء","level":"sector","parentId":"01M4D6BGEN9QDGX3095WSWMVDJ","sort":2,"isActive":1,"headUserId":null,"headNameEn":"Noura Al-Qahtani","headNameAr":"نورة القحطاني","headTitleEn":"Sector Head","headTitleAr":"رئيس القطاع","mandateEn":"Oversees strategy development, planning standards, programme monitoring and evaluation, and the theme teams for water, agriculture, climate, biodiversity, waste and air quality.","mandateAr":"يشرف على تطوير الاستراتيجية ومعايير التخطيط ومتابعة البرنامج وتقييمه وفرق المحاور للمياه والزراعة والمناخ والتنوع الأحيائي والنفايات وجودة الهواء.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":null,"responsibilitiesAr":null,"descriptionEn":null,"descriptionAr":null,"keyProjectsNote":null},{"id":"01M4D6BGEM8CD2PD6VB691TCQP","code":"SPD","nameEn":"Strategy Development","nameAr":"إدارة تطوير الاستراتيجية","level":"department","parentId":"01M4D6CAGXNZAHAF8RXASHE207","sort":3,"isActive":1,"headUserId":"01M4D6BHEQP10YDP9M2S6Q22GQ","headNameEn":"Abdulaziz Al-Dosari","headNameAr":"عبدالعزيز الدوسري","headTitleEn":"Department Director","headTitleAr":"مدير الإدارة","mandateEn":"Owns the Programme Strategy of the Office (the Strategy Office). Maintains its goals, results chain and change log, and prepares the annual review.","mandateAr":"تملك استراتيجية مكتب البرنامج (مكتب الاستراتيجية). تحافظ على أهدافها وسلسلة نتائجها وسجل تغييراتها وتعد المراجعة السنوية.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":"Develops the Programme Strategy, institutional modernisation, and excellence programmes with partner entities.","responsibilitiesAr":"تطور استراتيجية المكتب وبرامج التحديث المؤسسي والتميز مع الجهات الشريكة.","descriptionEn":"The Policy and Institutional Development Department designs the governance model of the Programme Office and advises on policy coherence across the national environment strategy themes. It supports regulatory reform proposals, delivery governance and capability building across delivery entities.","descriptionAr":"تصمم إدارة السياسات والتطوير المؤسسي نموذج حوكمة مكتب البرنامج وتقدم المشورة بشأن اتساق السياسات عبر محاور الاستراتيجية الوطنية للبيئة. وتدعم مقترحات الإصلاح التنظيمي وحوكمة التنفيذ وبناء القدرات لدى الجهات المنفذة.","keyProjectsNote":null},{"id":"01M4D6CAGYP0HZ6XYMWHB2BYZT","code":"PQS","nameEn":"Planning Quality and Standards","nameAr":"إدارة جودة الخطط والمعايير","level":"department","parentId":"01M4D6CAGXNZAHAF8RXASHE207","sort":4,"isActive":1,"headUserId":null,"headNameEn":"Reem Al-Shehri","headNameAr":"ريم الشهري","headTitleEn":"Department Director","headTitleAr":"مدير الإدارة","mandateEn":"Issues the results framework manual and templates, and reviews the quality of sector and entity strategies against them.","mandateAr":"تصدر دليل إطار النتائج ونماذجه، وتراجع جودة استراتيجيات القطاعات والجهات وفقاً له.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":null,"responsibilitiesAr":null,"descriptionEn":null,"descriptionAr":null,"keyProjectsNote":null},{"id":"01M4D6BGEN0X0HZVKB2P6E6678","code":"PMD","nameEn":"Programme Monitoring","nameAr":"إدارة متابعة البرنامج","level":"department","parentId":"01M4D6CAGXNZAHAF8RXASHE207","sort":5,"isActive":1,"headUserId":"01M4D6BHF6AGFKMMP55YD3AM5K","headNameEn":"Saud Al-Otaibi","headNameAr":"سعود العتيبي","headTitleEn":"Department Director","headTitleAr":"مدير الإدارة","mandateEn":"Runs the monitoring framework and the reporting cycle for the National Environment Strategy, and consolidates progress from entities into the delivery dashboard.","mandateAr":"تدير إطار المتابعة ودورة إعداد التقارير للاستراتيجية الوطنية للبيئة، وتجمع تقدم الجهات في لوحة متابعة التنفيذ.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":"Owns the NES results framework: KPI collection, status updates, delivery reviews, and the evaluation calendar.","responsibilitiesAr":"تملك إطار نتائج الاستراتيجية الوطنية للبيئة: جمع مؤشرات الأداء وتحديثات الحالة ومراجعات الإنجاز وتقويم التقييم.","descriptionEn":"The Performance Monitoring and Compliance Department tracks delivery of programme initiatives and projects against plan, evaluates results and follows regulatory compliance and enforcement indicators published by the competent regulators.","descriptionAr":"تتابع إدارة متابعة الأداء والامتثال تنفيذ مبادرات البرنامج ومشاريعه مقارنة بالخطة، وتقيّم النتائج، وتتابع مؤشرات الامتثال التنظيمي والإنفاذ التي تنشرها الجهات التنظيمية المختصة.","keyProjectsNote":null},{"id":"01M4D6CAH1B06V0CWDVWH6ES37","code":"PEV","nameEn":"Programme Evaluation","nameAr":"إدارة تقييم البرنامج","level":"department","parentId":"01M4D6CAGXNZAHAF8RXASHE207","sort":6,"isActive":1,"headUserId":null,"headNameEn":"Hessa Al-Mutairi","headNameAr":"حصة المطيري","headTitleEn":"Department Director","headTitleAr":"مدير الإدارة","mandateEn":"Commissions and conducts evaluations of initiatives and outcomes, and feeds the lessons learned back into planning.","mandateAr":"تكلف بتقييمات المبادرات والنتائج وتجريها، وتعيد الدروس المستفادة إلى عملية التخطيط.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":null,"responsibilitiesAr":null,"descriptionEn":null,"descriptionAr":null,"keyProjectsNote":null},{"id":"01M4D6CAH2PKKDJ4K58DZVRRNW","code":"ISU","nameEn":"Implementation Support","nameAr":"إدارة دعم التنفيذ","level":"department","parentId":"01M4D6CAGXNZAHAF8RXASHE207","sort":7,"isActive":1,"headUserId":null,"headNameEn":"Majed Al-Ghamdi","headNameAr":"ماجد الغامدي","headTitleEn":"Department Director","headTitleAr":"مدير الإدارة","mandateEn":"Supports entities whose initiatives are lagging with diagnostics, troubleshooting sessions and tailored support packages.","mandateAr":"تدعم الجهات المتأخرة مبادراتها بالتشخيص وجلسات معالجة المعوقات وحزم الدعم المخصصة.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":null,"responsibilitiesAr":null,"descriptionEn":null,"descriptionAr":null,"keyProjectsNote":null},{"id":"01M4D6CAH2Z16QWD7SDJF5XMQ9","code":"SCN","nameEn":"Scenarios and Signals","nameAr":"إدارة السيناريوهات والإشارات","level":"department","parentId":"01M4D6CAGXNZAHAF8RXASHE207","sort":8,"isActive":1,"headUserId":null,"headNameEn":"Lama Al-Zahrani","headNameAr":"لمى الزهراني","headTitleEn":"Department Director","headTitleAr":"مدير الإدارة","mandateEn":"Builds scenario sets for the environmental targets of Saudi Vision 2030 and tracks weak signals that may change the planning context.","mandateAr":"تبني مجموعات سيناريوهات للمستهدفات البيئية في رؤية السعودية 2030 وترصد الإشارات المبكرة التي قد تغير سياق التخطيط.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":null,"responsibilitiesAr":null,"descriptionEn":null,"descriptionAr":null,"keyProjectsNote":null},{"id":"01M4D6BGENG69HJJCBAM584JAY","code":"FRS","nameEn":"Foresight and Risk","nameAr":"إدارة الاستشراف والمخاطر","level":"department","parentId":"01M4D6CAGXNZAHAF8RXASHE207","sort":9,"isActive":1,"headUserId":"01M4D6BHF44SK2EWVZFR2XDBGM","headNameEn":"Turki Al-Anazi","headNameAr":"تركي العنزي","headTitleEn":"Department Director","headTitleAr":"مدير الإدارة","mandateEn":"Scans the horizon for environmental risks and opportunities and prepares the quarterly strategic risk briefing for leadership.","mandateAr":"تمسح الأفق بحثاً عن المخاطر والفرص البيئية وتعد إحاطة المخاطر الاستراتيجية الربع سنوية للقيادة.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":"Runs horizon scanning, the signals pipeline, environmental risk registers, and futures work that feeds the mid-term review.","responsibilitiesAr":"تدير استشراف الأفق وخط الإشارات وسجلات المخاطر البيئية وأعمال المستقبلات التي تغذي مراجعة منتصف المدة.","descriptionEn":"The Climate, Foresight and Risk Department scans emerging climate, water and land risks, builds scenarios for the programme and maintains the programme risk register. It supports the Saudi Green Initiative and Middle East Green Initiative reporting lines.","descriptionAr":"ترصد إدارة المناخ والاستشراف والمخاطر المخاطر الناشئة في المناخ والمياه والأراضي، وتبني سيناريوهات للبرنامج، وتدير سجل مخاطر البرنامج. وتدعم مسارات إعداد التقارير لمبادرة السعودية الخضراء ومبادرة الشرق الأوسط الأخضر.","keyProjectsNote":null},{"id":"01M4D6CAH2M4YTAQ9BTVWE0B89","code":"PLB","nameEn":"Policy Lab","nameAr":"مختبر السياسات","level":"department","parentId":"01M4D6CAGXNZAHAF8RXASHE207","sort":10,"isActive":1,"headUserId":null,"headNameEn":"Dalal Al-Subaie","headNameAr":"دلال السبيعي","headTitleEn":"Department Director","headTitleAr":"مدير الإدارة","mandateEn":"Tests proposed policies and regulations with simulation models and structured trials before they are adopted.","mandateAr":"يختبر السياسات والأنظمة المقترحة بنماذج المحاكاة والتجارب المنظمة قبل اعتمادها.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":null,"responsibilitiesAr":null,"descriptionEn":null,"descriptionAr":null,"keyProjectsNote":null},{"id":"01M4D6CAH27V6Q5ZA7TPJGRZM1","code":"BIN","nameEn":"Behavioural Insights","nameAr":"إدارة الرؤى السلوكية","level":"department","parentId":"01M4D6CAGXNZAHAF8RXASHE207","sort":11,"isActive":1,"headUserId":null,"headNameEn":"Wafa Al-Rashidi","headNameAr":"وفاء الرشيدي","headTitleEn":"Department Director","headTitleAr":"مدير الإدارة","mandateEn":"Designs and evaluates behavioural trials on water use, waste and other priorities where behaviour drives results.","mandateAr":"تصمم تجارب سلوكية وتقيمها في مجالات استهلاك المياه والنفايات وغيرها مما يؤثر فيه السلوك في النتائج.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":null,"responsibilitiesAr":null,"descriptionEn":null,"descriptionAr":null,"keyProjectsNote":null},{"id":"01M4D6BGEMHR52SA8N2ZYYRJDD","code":"WSD","nameEn":"Water Security","nameAr":"إدارة الأمن المائي","level":"department","parentId":"01M4D6CAGXNZAHAF8RXASHE207","sort":12,"isActive":1,"headUserId":"01M4D6BHEV9G5W4Q3XS5WPTZNG","headNameEn":"Khalid Al-Salem","headNameAr":"خالد السالم","headTitleEn":"Department Director","headTitleAr":"مدير الإدارة","mandateEn":"Supports the water security theme: demand and supply balance, resource efficiency and coordination with water sector entities.","mandateAr":"تدعم محور الأمن المائي: التوازن بين الطلب والإمداد وكفاءة الموارد والتنسيق مع جهات قطاع المياه.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":"Leads the water security theme of the NES: demand and supply balance, desalination and wastewater reuse, and the water policy pipeline with MEWA, SWA and NWC.","responsibilitiesAr":"تقود محور الأمن المائي في الاستراتيجية الوطنية للبيئة: توازن العرض والطلب وتحلية المياه وإعادة استخدام المياه المعالجة وخط سياسات المياه مع وزارة البيئة والمياه والزراعة والهيئة السعودية للمياه وشركة المياه الوطنية.","descriptionEn":"The Water and Agriculture Economics Department analyses the economics of water supply, demand management, food production and trade. It prepares cost and benefit cases for programme initiatives, tariff and investment options, and tracks the economic indicators that frame the Water Security and Agriculture and Food Security themes.","descriptionAr":"تحلل إدارة اقتصاديات المياه والزراعة اقتصاديات إمدادات المياه وإدارة الطلب والإنتاج الغذائي والتجارة. وتعد دراسات التكلفة والعائد لمبادرات البرنامج وخيارات التعرفة والاستثمار، وتتابع المؤشرات الاقتصادية التي تؤطر محوري الأمن المائي والأمن الغذائي والزراعة.","keyProjectsNote":null},{"id":"01M4D6BGEM49D56VJH4VTHV705","code":"AFD","nameEn":"Agriculture and Food Security","nameAr":"إدارة الأمن الغذائي والزراعة","level":"department","parentId":"01M4D6CAGXNZAHAF8RXASHE207","sort":13,"isActive":1,"headUserId":"01M4D6BHF37BQ4PDMG2KHFXHXX","headNameEn":"Maha Al-Yami","headNameAr":"مها اليامي","headTitleEn":"Department Director","headTitleAr":"مدير الإدارة","mandateEn":"Supports the agriculture and food security theme: sustainable production, agricultural water use and food supply resilience.","mandateAr":"تدعم محور الأمن الغذائي والزراعة: الإنتاج المستدام واستخدام المياه الزراعية ومرونة الإمداد الغذائي.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":"Leads the agriculture and food security theme: sustainable farming, agricultural water use, food supply resilience, and alignment with GFSA and FAO.","responsibilitiesAr":"تقود محور الأمن الغذائي والزراعة: الزراعة المستدامة واستخدام المياه الزراعية ومرونة إمدادات الغذاء والمواءمة مع الهيئة العامة للأمن الغذائي ومنظمة الفاو.","descriptionEn":"The Biodiversity, Land and Community Programmes Department coordinates the programmes that protect habitats, restore degraded land and engage communities, working with the National Center for Wildlife and the National Center for Vegetation Cover Development and Combating Desertification.","descriptionAr":"تنسق إدارة برامج التنوع الأحيائي والأراضي والمجتمع البرامج التي تحمي الموائل وتعيد تأهيل الأراضي المتدهورة وتشرك المجتمعات، بالتعاون مع المركز الوطني للحياة الفطرية والمركز الوطني لتنمية الغطاء النباتي ومكافحة التصحر.","keyProjectsNote":null},{"id":"01M4D6CAH20B6QCZ2XSW9HDWM9","code":"CLD","nameEn":"Climate and Environment","nameAr":"إدارة المناخ والبيئة","level":"department","parentId":"01M4D6CAGXNZAHAF8RXASHE207","sort":14,"isActive":1,"headUserId":null,"headNameEn":"Bandar Al-Shammari","headNameAr":"بندر الشمري","headTitleEn":"Department Director","headTitleAr":"مدير الإدارة","mandateEn":"Supports the climate and environment theme: emissions, adaptation, and alignment with national and international climate commitments.","mandateAr":"تدعم محور المناخ والبيئة: الانبعاثات والتكيف والمواءمة مع الالتزامات المناخية الوطنية والدولية.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":null,"responsibilitiesAr":null,"descriptionEn":null,"descriptionAr":null,"keyProjectsNote":null},{"id":"01M4D6CAH3Q4H7245BGG64NVGB","code":"BLD","nameEn":"Biodiversity and Land","nameAr":"إدارة التنوع الأحيائي والأراضي","level":"department","parentId":"01M4D6CAGXNZAHAF8RXASHE207","sort":15,"isActive":1,"headUserId":null,"headNameEn":"Sarah Al-Juhani","headNameAr":"سارة الجهني","headTitleEn":"Department Director","headTitleAr":"مدير الإدارة","mandateEn":"Supports the biodiversity and land theme: habitat protection, vegetation cover and land degradation.","mandateAr":"تدعم محور التنوع الأحيائي والأراضي: حماية الموائل والغطاء النباتي وتدهور الأراضي.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":null,"responsibilitiesAr":null,"descriptionEn":null,"descriptionAr":null,"keyProjectsNote":null},{"id":"01M4D6CAH3H9MPXEDTHC9MT6MT","code":"WCD","nameEn":"Waste and Circular Economy","nameAr":"إدارة النفايات والاقتصاد الدائري","level":"department","parentId":"01M4D6CAGXNZAHAF8RXASHE207","sort":16,"isActive":1,"headUserId":null,"headNameEn":"Yousef Al-Maliki","headNameAr":"يوسف المالكي","headTitleEn":"Department Director","headTitleAr":"مدير الإدارة","mandateEn":"Supports the waste and circular economy theme: waste reduction, recovery and recycling, and circular practices across sectors.","mandateAr":"تدعم محور النفايات والاقتصاد الدائري: خفض النفايات واستردادها وتدويرها والممارسات الدائرية في القطاعات.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":null,"responsibilitiesAr":null,"descriptionEn":null,"descriptionAr":null,"keyProjectsNote":null},{"id":"01M4D6CAH3F8R1PDW39RMTE8V1","code":"AQD","nameEn":"Air Quality","nameAr":"إدارة جودة الهواء","level":"department","parentId":"01M4D6CAGXNZAHAF8RXASHE207","sort":17,"isActive":1,"headUserId":null,"headNameEn":"Anwar Al-Harthi","headNameAr":"أنور الحارثي","headTitleEn":"Department Director","headTitleAr":"مدير الإدارة","mandateEn":"Supports the air quality theme: monitoring networks, emission sources and progress against air quality objectives.","mandateAr":"تدعم محور جودة الهواء: شبكات الرصد ومصادر الانبعاثات والتقدم نحو أهداف جودة الهواء.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":null,"responsibilitiesAr":null,"descriptionEn":null,"descriptionAr":null,"keyProjectsNote":null},{"id":"01M4D6CAH3TRDCQBZRWA7CRDHM","code":"RAS","nameEn":"Regulatory Affairs Sector","nameAr":"قطاع الشؤون التنظيمية","level":"sector","parentId":"01M4D6BGEN9QDGX3095WSWMVDJ","sort":18,"isActive":1,"headUserId":null,"headNameEn":"Abeer Al-Tamimi","headNameAr":"عبير التميمي","headTitleEn":"Sector Head","headTitleAr":"رئيس القطاع","mandateEn":"Oversees how environmental regulation is tracked, reviewed and understood across the Office and its partner entities.","mandateAr":"يشرف على كيفية تتبع الأنظمة البيئية ومراجعتها وفهمها داخل المكتب والجهات الشريكة.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":null,"responsibilitiesAr":null,"descriptionEn":null,"descriptionAr":null,"keyProjectsNote":null},{"id":"01M4D6CAH3BF25TQ3FKMJQRKF3","code":"RCM","nameEn":"Regulatory Compliance Monitoring","nameAr":"إدارة متابعة الامتثال التنظيمي","level":"department","parentId":"01M4D6CAH3TRDCQBZRWA7CRDHM","sort":19,"isActive":1,"headUserId":null,"headNameEn":"Nasser Al-Khaldi","headNameAr":"ناصر الخالدي","headTitleEn":"Department Director","headTitleAr":"مدير الإدارة","mandateEn":"Maintains the regulatory register, tracks changes to environmental regulations and reports compliance status to leadership.","mandateAr":"تحافظ على السجل التنظيمي وتتتبع التغييرات في الأنظمة البيئية وترفع حالة الامتثال إلى القيادة.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":null,"responsibilitiesAr":null,"descriptionEn":null,"descriptionAr":null,"keyProjectsNote":null},{"id":"01M4D6CAH3AP4RB0EW3K5V8KR3","code":"RLR","nameEn":"Regulatory and Legislative Review","nameAr":"إدارة المراجعة التنظيمية والتشريعية","level":"department","parentId":"01M4D6CAH3TRDCQBZRWA7CRDHM","sort":20,"isActive":1,"headUserId":null,"headNameEn":"Joud Al-Bishi","headNameAr":"جود البيشي","headTitleEn":"Department Director","headTitleAr":"مدير الإدارة","mandateEn":"Reviews draft environmental regulations and their impact, and supports the Regulatory Review Panel.","mandateAr":"تراجع مشاريع الأنظمة البيئية وأثرها، وتدعم لجنة المراجعة التنظيمية.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":null,"responsibilitiesAr":null,"descriptionEn":null,"descriptionAr":null,"keyProjectsNote":null},{"id":"01M4D6CAH4X02H4MT1ECBN07NB","code":"DKS","nameEn":"Data and Knowledge Sector","nameAr":"قطاع البيانات والمعرفة","level":"sector","parentId":"01M4D6BGEN9QDGX3095WSWMVDJ","sort":21,"isActive":1,"headUserId":null,"headNameEn":"Fahad Al-Zayed","headNameAr":"فهد الزايد","headTitleEn":"Sector Head","headTitleAr":"رئيس القطاع","mandateEn":"Oversees environmental data production, governance and dissemination, and the knowledge management of the Office.","mandateAr":"يشرف على إنتاج البيانات البيئية وحوكمتها ونشرها، وعلى إدارة المعرفة في المكتب.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":null,"responsibilitiesAr":null,"descriptionEn":null,"descriptionAr":null,"keyProjectsNote":null},{"id":"01M4D6BGEHC8RJHJPQ0481V7JY","code":"EDA","nameEn":"Environmental Data Affairs","nameAr":"إدارة شؤون البيانات البيئية","level":"department","parentId":"01M4D6CAH4X02H4MT1ECBN07NB","sort":22,"isActive":1,"headUserId":"01M4D6BHEPY18BP31WZMBVQ2DJ","headNameEn":"Ghada Al-Mansour","headNameAr":"غادة المنصور","headTitleEn":"Department Director","headTitleAr":"مدير الإدارة","mandateEn":"Owns the strategy for trusted environmental data and statistics and coordinates data requests and partnerships with entities.","mandateAr":"تملك استراتيجية البيانات والإحصاءات البيئية الموثوقة وتنسق طلبات البيانات والشراكات مع الجهات.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":"Coordinates environmental data governance, data sharing agreements, and the registers behind the indicators.","responsibilitiesAr":"تنسق حوكمة البيانات البيئية واتفاقيات تبادل البيانات والسجلات التي تقوم عليها المؤشرات.","descriptionEn":"The Data and Digital Platforms Department runs the Programme Office data layer. It sets data governance standards, data sharing arrangements and quality rules for the environmental, water and agricultural data that flows in from MEWA, NCEC, NCW, NCVC, MWAN and the Environment Fund, and it keeps the programme data catalogue current.","descriptionAr":"تدير إدارة البيانات والمنصات الرقمية طبقة البيانات في مكتب البرنامج. وتضع معايير حوكمة البيانات وترتيبات تبادلها وقواعد جودتها للبيانات البيئية والمائية والزراعية الواردة من وزارة البيئة والمياه والزراعة والمركز الوطني للرقابة على الالتزام البيئي والمركز الوطني للحياة الفطرية والمركز الوطني لتنمية الغطاء النباتي ومكافحة التصحر والمركز الوطني لإدارة النفايات وصندوق البيئة، وتحافظ على تحديث فهرس بيانات البرنامج.","keyProjectsNote":null},{"id":"01M4D6BGEJJ8DT77CSYCK82ZBV","code":"DOP","nameEn":"Data Operations","nameAr":"إدارة عمليات البيانات","level":"department","parentId":"01M4D6CAH4X02H4MT1ECBN07NB","sort":23,"isActive":1,"headUserId":"01M4D6BHEP9TW2034D56782GZ9","headNameEn":"Ibrahim Al-Sudairi","headNameAr":"إبراهيم السديري","headTitleEn":"Department Director","headTitleAr":"مدير الإدارة","mandateEn":"Runs environmental monitoring data collection, remote sensing feeds and administrative records intake, and the open data release calendar.","mandateAr":"تدير جمع بيانات الرصد البيئي وتغذيات الاستشعار عن بعد واستلام السجلات الإدارية وتقويم إصدار البيانات المفتوحة.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":"Runs environmental monitoring operations, remote sensing and administrative record collection, and the production of data releases.","responsibilitiesAr":"تدير عمليات الرصد البيئي والاستشعار عن بعد وجمع السجلات الإدارية وإنتاج إصدارات البيانات.","descriptionEn":"The Monitoring and Field Operations Department plans and runs field monitoring campaigns, household water and waste surveys and administrative data collection with partner entities. It manages sampling, data capture and the timely release of monitoring products to the scorecard.","descriptionAr":"تخطط إدارة المراقبة والعمليات الميدانية لحملات الرصد الميداني والمسوح الأسرية للمياه والنفايات وجمع البيانات الإدارية مع الجهات الشريكة وتنفذها. وتدير العينات وإدخال البيانات والإتاحة في الوقت المناسب لمنتجات الرصد على بطاقة المؤشرات.","keyProjectsNote":null},{"id":"01M4D6BGEJTNA5C60HM189RKHW","code":"DSY","nameEn":"Data Systems","nameAr":"إدارة نظم البيانات","level":"department","parentId":"01M4D6CAH4X02H4MT1ECBN07NB","sort":24,"isActive":1,"headUserId":"01M4D6BGHAKBD28V6BPQ7S7XE3","headNameEn":"Mishal Al-Dawsari","headNameAr":"مشعل الدوسري","headTitleEn":"Department Director","headTitleAr":"مدير الإدارة","mandateEn":"Builds and operates the data platforms, catalogues and pipelines that serve the Office.","mandateAr":"تبني وتشغل منصات البيانات والفهارس وخطوط المعالجة التي تخدم المكتب.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":"Builds and maintains the data production systems, classifications, and quality frameworks.","responsibilitiesAr":"تبني وتشغل نظم إنتاج البيانات والتصنيفات وأطر الجودة.","descriptionEn":"The Environmental Statistics and Systems Department maintains the indicator methodology, classifications and technical systems behind the programme scorecard. It aligns indicator definitions with international standards and with GASTAT practice, and it operates the systems that compute and publish the headline environment, water and agriculture indicators.","descriptionAr":"تحافظ إدارة الإحصاءات والنظم البيئية على منهجية المؤشرات والتصنيفات والنظم التقنية التي تقوم عليها بطاقة مؤشرات البرنامج. وتواءم تعريفات المؤشرات مع المعايير الدولية وممارسات الهيئة العامة للإحصاء، وتشغّل النظم التي تحتسب وتنشر المؤشرات الرئيسية للبيئة والمياه والزراعة.","keyProjectsNote":null},{"id":"01M4D6CAH4W5AVSABK3GFKSWC9","code":"DQS","nameEn":"Data Quality and Standards","nameAr":"إدارة جودة البيانات والمعايير","level":"department","parentId":"01M4D6CAH4X02H4MT1ECBN07NB","sort":25,"isActive":1,"headUserId":null,"headNameEn":"Shaima Al-Fayez","headNameAr":"شيماء الفايز","headTitleEn":"Department Director","headTitleAr":"مدير الإدارة","mandateEn":"Defines quality assurance rules, metadata standards and classifications, and signs off datasets before release.","mandateAr":"تحدد قواعد ضمان الجودة ومعايير البيانات الوصفية والتصنيفات، وتعتمد مجموعات البيانات قبل إصدارها.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":null,"responsibilitiesAr":null,"descriptionEn":null,"descriptionAr":null,"keyProjectsNote":null},{"id":"01M4D6CAH47FXC5G3P4JV7PS0F","code":"EAS","nameEn":"Environmental Accounts and Statistics","nameAr":"إدارة الحسابات والإحصاءات البيئية","level":"department","parentId":"01M4D6CAH4X02H4MT1ECBN07NB","sort":26,"isActive":1,"headUserId":null,"headNameEn":"Rakan Al-Sharif","headNameAr":"راكان الشريف","headTitleEn":"Department Director","headTitleAr":"مدير الإدارة","mandateEn":"Compiles environmental accounts and the Annual Environment Statistical Digest (illustrative) from entity and survey sources.","mandateAr":"تعد الحسابات البيئية وملخص الإحصاءات البيئية السنوي (توضيحي) من مصادر الجهات والمسوح.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":null,"responsibilitiesAr":null,"descriptionEn":null,"descriptionAr":null,"keyProjectsNote":null},{"id":"01M4D6CAH5B7NG3WSDB4KQWVYD","code":"DGS","nameEn":"Data Governance and Security","nameAr":"إدارة حوكمة البيانات وأمنها","level":"department","parentId":"01M4D6CAH4X02H4MT1ECBN07NB","sort":27,"isActive":1,"headUserId":null,"headNameEn":"Lujain Al-Obaidi","headNameAr":"لجين العبيدي","headTitleEn":"Department Director","headTitleAr":"مدير الإدارة","mandateEn":"Sets the data governance policies, information classification and security rules, and supports the Data Governance Board.","mandateAr":"تضع سياسات حوكمة البيانات وتصنيف المعلومات وقواعد الأمن، وتدعم مجلس حوكمة البيانات.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":null,"responsibilitiesAr":null,"descriptionEn":null,"descriptionAr":null,"keyProjectsNote":null},{"id":"01M4D6CAH53MCRHY7A39399W58","code":"KMD","nameEn":"Knowledge Management","nameAr":"إدارة المعرفة","level":"department","parentId":"01M4D6CAH4X02H4MT1ECBN07NB","sort":28,"isActive":1,"headUserId":null,"headNameEn":"Hind Al-Ajmi","headNameAr":"هند العجمي","headTitleEn":"Department Director","headTitleAr":"مدير الإدارة","mandateEn":"Stewards institutional memory: the document library, handover of knowledge when roles change, and expert and lessons registers.","mandateAr":"تتولى رعاية الذاكرة المؤسسية: مكتبة الوثائق وتسليم المعرفة عند تغير الأدوار وسجلات الخبراء والدروس المستفادة.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":null,"responsibilitiesAr":null,"descriptionEn":null,"descriptionAr":null,"keyProjectsNote":null},{"id":"01M4D6BGENB6WPFZF0BJRG1PX3","code":"DIG","nameEn":"Digital","nameAr":"إدارة الرقمنة","level":"department","parentId":"01M4D6CAH5H14KDXZP670RRKHD","sort":29,"isActive":1,"headUserId":"01M4D6BHF8ZTSM8WQ4KK84M1E1","headNameEn":"Osama Al-Rumaih","headNameAr":"أسامة الرميح","headTitleEn":"Department Director","headTitleAr":"مدير الإدارة","mandateEn":"Runs the Office''s digital workplace, infrastructure, information security operations and business continuity.","mandateAr":"تدير بيئة العمل الرقمية والبنية التحتية وعمليات أمن المعلومات واستمرارية الأعمال في المكتب.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":"Operates EnviroAI and the Office''s digital platforms, integrations, and information security posture.","responsibilitiesAr":"تشغل EnviroAI والمنصات الرقمية للمكتب وتكاملاتها ووضعها في أمن المعلومات.","descriptionEn":"The Information Technology Department builds and maintains the technology platform of the Programme Office, including the EnviroAI knowledge system, identity, security and the analytics environment.","descriptionAr":"تبني إدارة تقنية المعلومات المنصة التقنية لمكتب البرنامج وتحافظ عليها، بما في ذلك منظومة المعرفة EnviroAI والهوية والأمن وبيئة التحليلات.","keyProjectsNote":null},{"id":"01M4D6CAH58S164TAB88ATBPNN","code":"DTO","nameEn":"Digital Transformation Office","nameAr":"مكتب التحول الرقمي","level":"office","parentId":"01M4D6BGEN9QDGX3095WSWMVDJ","sort":30,"isActive":1,"headUserId":null,"headNameEn":"Ahmed Al-Nafisi","headNameAr":"أحمد النفيسي","headTitleEn":"Head of Office","headTitleAr":"رئيس المكتب","mandateEn":"Coordinates the Office''s digital transformation portfolio and process automation across units.","mandateAr":"ينسق محفظة التحول الرقمي في المكتب وأتمتة العمليات بين الوحدات.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":null,"responsibilitiesAr":null,"descriptionEn":null,"descriptionAr":null,"keyProjectsNote":null},{"id":"01M4D6CAH5RK2PHTPB3RX644SG","code":"PAR","nameEn":"Partnerships and International Commitments","nameAr":"إدارة الشراكات والالتزامات الدولية","level":"department","parentId":"01M4D6BGEN9QDGX3095WSWMVDJ","sort":31,"isActive":1,"headUserId":null,"headNameEn":"Latifa Al-Moammar","headNameAr":"لطيفة المعمر","headTitleEn":"Department Director","headTitleAr":"مدير الإدارة","mandateEn":"Manages partnerships with entities, universities and international organisations, and engagement with global indicators and commitments.","mandateAr":"تدير الشراكات مع الجهات والجامعات والمنظمات الدولية، والتعامل مع المؤشرات والالتزامات العالمية.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":null,"responsibilitiesAr":null,"descriptionEn":null,"descriptionAr":null,"keyProjectsNote":null},{"id":"01M4D6CAH5PG0GZ86833HGXMP4","code":"COM","nameEn":"Communications","nameAr":"إدارة الاتصال","level":"department","parentId":"01M4D6BGEN9QDGX3095WSWMVDJ","sort":32,"isActive":1,"headUserId":null,"headNameEn":"Badr Al-Hazmi","headNameAr":"بدر الحازمي","headTitleEn":"Department Director","headTitleAr":"مدير الإدارة","mandateEn":"Plans and delivers the Office''s publications, public communication and media relations.","mandateAr":"تخطط لإصدارات المكتب وتواصله مع الجمهور وعلاقاته الإعلامية وتنفذها.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":null,"responsibilitiesAr":null,"descriptionEn":null,"descriptionAr":null,"keyProjectsNote":null},{"id":"01M4D6CAH5H14KDXZP670RRKHD","code":"CSS","nameEn":"Corporate Services Sector","nameAr":"قطاع الخدمات المؤسسية","level":"sector","parentId":"01M4D6BGEN9QDGX3095WSWMVDJ","sort":33,"isActive":1,"headUserId":null,"headNameEn":"Ziyad Al-Habib","headNameAr":"زياد الحبيب","headTitleEn":"Sector Head","headTitleAr":"رئيس القطاع","mandateEn":"Oversees capability development, human resources, finance, administration and secretariat services of the Office.","mandateAr":"يشرف على تنمية القدرات والموارد البشرية والمالية والشؤون الإدارية وخدمات الأمانة في المكتب.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":null,"responsibilitiesAr":null,"descriptionEn":null,"descriptionAr":null,"keyProjectsNote":null},{"id":"01M4D6CAH58AFT3SG1CKSBAGCW","code":"CAP","nameEn":"Capability Development","nameAr":"إدارة تنمية القدرات","level":"department","parentId":"01M4D6CAH5H14KDXZP670RRKHD","sort":34,"isActive":1,"headUserId":null,"headNameEn":"Amal Al-Rowaili","headNameAr":"أمل الرويلي","headTitleEn":"Department Director","headTitleAr":"مدير الإدارة","mandateEn":"Designs training and development programmes for Office staff and for the planning teams of partner entities.","mandateAr":"تصمم برامج التدريب والتطوير لموظفي المكتب ولفرق التخطيط في الجهات الشريكة.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":null,"responsibilitiesAr":null,"descriptionEn":null,"descriptionAr":null,"keyProjectsNote":null},{"id":"01M4D6CAH6QSTZH98061MK95ZN","code":"HR","nameEn":"Human Resources","nameAr":"إدارة الموارد البشرية","level":"department","parentId":"01M4D6CAH5H14KDXZP670RRKHD","sort":35,"isActive":1,"headUserId":null,"headNameEn":"Sultan Al-Buraik","headNameAr":"سلطان البريك","headTitleEn":"Department Director","headTitleAr":"مدير الإدارة","mandateEn":"Manages recruitment, employee relations, performance and the HR policies of the Office, including Saudization planning where it applies.","mandateAr":"تدير الاستقطاب وعلاقات الموظفين والأداء وسياسات الموارد البشرية في المكتب، بما في ذلك تخطيط التوطين حيثما ينطبق.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":null,"responsibilitiesAr":null,"descriptionEn":null,"descriptionAr":null,"keyProjectsNote":null},{"id":"01M4D6CAH6CVYWV9ZQBAD2FYV7","code":"FIN","nameEn":"Finance and Administration","nameAr":"إدارة المالية والشؤون الإدارية","level":"department","parentId":"01M4D6CAH5H14KDXZP670RRKHD","sort":36,"isActive":1,"headUserId":null,"headNameEn":"Mansour Al-Qarni","headNameAr":"منصور القرني","headTitleEn":"Department Director","headTitleAr":"مدير الإدارة","mandateEn":"Prepares and controls the Office budget, procurement and administrative services.","mandateAr":"تعد ميزانية المكتب وتراقبها وتدير المشتريات والخدمات الإدارية.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":null,"responsibilitiesAr":null,"descriptionEn":null,"descriptionAr":null,"keyProjectsNote":null},{"id":"01M4D6CAH6NZCGHFTBRR8T2SM0","code":"PSA","nameEn":"Programme Secretariat Affairs","nameAr":"إدارة شؤون الأمانة","level":"department","parentId":"01M4D6CAH5H14KDXZP670RRKHD","sort":37,"isActive":1,"headUserId":null,"headNameEn":"Danah Al-Sulaiman","headNameAr":"دانة السليمان","headTitleEn":"Department Director","headTitleAr":"مدير الإدارة","mandateEn":"Runs the secretariat of the Programme Steering Committee and the Office committees, and follows up their decisions.","mandateAr":"تتولى أمانة اللجنة التوجيهية للبرنامج ولجان المكتب وتتابع قراراتها.","mandateSourceUrl":"","mandateSourceUrlAr":"","mandateFetchedAt":"2026-01-01T00:00:00.000Z","responsibilitiesEn":null,"responsibilitiesAr":null,"descriptionEn":null,"descriptionAr":null,"keyProjectsNote":null}],"levels":[{"code":"secretary_general","nameEn":"Programme Director","nameAr":"مدير البرنامج","sort":0},{"code":"sector","nameEn":"Sector","nameAr":"القطاع","sort":1},{"code":"office","nameEn":"Office","nameAr":"المكتب","sort":2},{"code":"department","nameEn":"Department","nameAr":"الإدارة","sort":3},{"code":"section","nameEn":"Section","nameAr":"القسم","sort":4}]}', 'initial Programme Office structure (CR08 seed)');
