INSERT INTO "org_units" ("id", "code", "name_en", "name_ar", "description_en", "description_ar", "head_user_id", "parent_id", "created_at", "updated_at", "responsibilities_en", "responsibilities_ar", "key_projects_note", "level", "mandate_en", "mandate_ar", "mandate_source_url", "mandate_source_url_ar", "mandate_fetched_at", "head_name_en", "head_name_ar", "head_title_en", "head_title_ar", "sort", "is_active") VALUES
('01M4D6BGEHC8RJHJPQ0481V7JY', 'EDA', 'Environmental Data Affairs', 'إدارة شؤون البيانات البيئية', 'The Data and Digital Platforms Department runs the Programme Office data layer. It sets data governance standards, data sharing arrangements and quality rules for the environmental, water and agricultural data that flows in from MEWA, NCEC, NCW, NCVC, MWAN and the Environment Fund, and it keeps the programme data catalogue current.', 'تدير إدارة البيانات والمنصات الرقمية طبقة البيانات في مكتب البرنامج. وتضع معايير حوكمة البيانات وترتيبات تبادلها وقواعد جودتها للبيانات البيئية والمائية والزراعية الواردة من وزارة البيئة والمياه والزراعة والمركز الوطني للرقابة على الالتزام البيئي والمركز الوطني للحياة الفطرية والمركز الوطني لتنمية الغطاء النباتي ومكافحة التصحر والمركز الوطني لإدارة النفايات وصندوق البيئة، وتحافظ على تحديث فهرس بيانات البرنامج.', '01M4D6BHEPY18BP31WZMBVQ2DJ', '01M4D6CAH4X02H4MT1ECBN07NB', '2026-10-08T07:23:58.764Z', '2026-10-08T07:24:25.508Z', 'Coordinates environmental data governance, data sharing agreements, and the registers behind the indicators.', 'تنسق حوكمة البيانات البيئية واتفاقيات تبادل البيانات والسجلات التي تقوم عليها المؤشرات.', NULL, 'department', 'Owns the strategy for trusted environmental data and statistics and coordinates data requests and partnerships with entities.', 'تملك استراتيجية البيانات والإحصاءات البيئية الموثوقة وتنسق طلبات البيانات والشراكات مع الجهات.', '', '', '2026-01-01T00:00:00.000Z', 'Ghada Al-Mansour', 'غادة المنصور', 'Department Director', 'مدير الإدارة', 22, 1),
('01M4D6BGEJTNA5C60HM189RKHW', 'DSY', 'Data Systems', 'إدارة نظم البيانات', 'The Environmental Statistics and Systems Department maintains the indicator methodology, classifications and technical systems behind the programme scorecard. It aligns indicator definitions with international standards and with GASTAT practice, and it operates the systems that compute and publish the headline environment, water and agriculture indicators.', 'تحافظ إدارة الإحصاءات والنظم البيئية على منهجية المؤشرات والتصنيفات والنظم التقنية التي تقوم عليها بطاقة مؤشرات البرنامج. وتواءم تعريفات المؤشرات مع المعايير الدولية وممارسات الهيئة العامة للإحصاء، وتشغّل النظم التي تحتسب وتنشر المؤشرات الرئيسية للبيئة والمياه والزراعة.', '01M4D6BGHAKBD28V6BPQ7S7XE3', '01M4D6CAH4X02H4MT1ECBN07NB', '2026-10-08T07:23:58.764Z', '2026-10-08T07:24:25.508Z', 'Builds and maintains the data production systems, classifications, and quality frameworks.', 'تبني وتشغل نظم إنتاج البيانات والتصنيفات وأطر الجودة.', NULL, 'department', 'Builds and operates the data platforms, catalogues and pipelines that serve the Office.', 'تبني وتشغل منصات البيانات والفهارس وخطوط المعالجة التي تخدم المكتب.', '', '', '2026-01-01T00:00:00.000Z', 'Mishal Al-Dawsari', 'مشعل الدوسري', 'Department Director', 'مدير الإدارة', 24, 1),
('01M4D6BGEJJ8DT77CSYCK82ZBV', 'DOP', 'Data Operations', 'إدارة عمليات البيانات', 'The Monitoring and Field Operations Department plans and runs field monitoring campaigns, household water and waste surveys and administrative data collection with partner entities. It manages sampling, data capture and the timely release of monitoring products to the scorecard.', 'تخطط إدارة المراقبة والعمليات الميدانية لحملات الرصد الميداني والمسوح الأسرية للمياه والنفايات وجمع البيانات الإدارية مع الجهات الشريكة وتنفذها. وتدير العينات وإدخال البيانات والإتاحة في الوقت المناسب لمنتجات الرصد على بطاقة المؤشرات.', '01M4D6BHEP9TW2034D56782GZ9', '01M4D6CAH4X02H4MT1ECBN07NB', '2026-10-08T07:23:58.764Z', '2026-10-08T07:24:25.508Z', 'Runs environmental monitoring operations, remote sensing and administrative record collection, and the production of data releases.', 'تدير عمليات الرصد البيئي والاستشعار عن بعد وجمع السجلات الإدارية وإنتاج إصدارات البيانات.', NULL, 'department', 'Runs environmental monitoring data collection, remote sensing feeds and administrative records intake, and the open data release calendar.', 'تدير جمع بيانات الرصد البيئي وتغذيات الاستشعار عن بعد واستلام السجلات الإدارية وتقويم إصدار البيانات المفتوحة.', '', '', '2026-01-01T00:00:00.000Z', 'Ibrahim Al-Sudairi', 'إبراهيم السديري', 'Department Director', 'مدير الإدارة', 23, 1),
('01M4D6BGEM8CD2PD6VB691TCQP', 'SPD', 'Strategy Development', 'إدارة تطوير الاستراتيجية', 'The Policy and Institutional Development Department designs the governance model of the Programme Office and advises on policy coherence across the national environment strategy themes. It supports regulatory reform proposals, delivery governance and capability building across delivery entities.', 'تصمم إدارة السياسات والتطوير المؤسسي نموذج حوكمة مكتب البرنامج وتقدم المشورة بشأن اتساق السياسات عبر محاور الاستراتيجية الوطنية للبيئة. وتدعم مقترحات الإصلاح التنظيمي وحوكمة التنفيذ وبناء القدرات لدى الجهات المنفذة.', '01M4D6BHEQP10YDP9M2S6Q22GQ', '01M4D6CAGXNZAHAF8RXASHE207', '2026-10-08T07:23:58.764Z', '2026-10-08T07:24:25.502Z', 'Develops the Programme Strategy, institutional modernisation, and excellence programmes with partner entities.', 'تطور استراتيجية المكتب وبرامج التحديث المؤسسي والتميز مع الجهات الشريكة.', NULL, 'department', 'Owns the Programme Strategy of the Office (the Strategy Office). Maintains its goals, results chain and change log, and prepares the annual review.', 'تملك استراتيجية مكتب البرنامج (مكتب الاستراتيجية). تحافظ على أهدافها وسلسلة نتائجها وسجل تغييراتها وتعد المراجعة السنوية.', '', '', '2026-01-01T00:00:00.000Z', 'Abdulaziz Al-Dosari', 'عبدالعزيز الدوسري', 'Department Director', 'مدير الإدارة', 3, 1),
('01M4D6BGEMHR52SA8N2ZYYRJDD', 'WSD', 'Water Security', 'إدارة الأمن المائي', 'The Water and Agriculture Economics Department analyses the economics of water supply, demand management, food production and trade. It prepares cost and benefit cases for programme initiatives, tariff and investment options, and tracks the economic indicators that frame the Water Security and Agriculture and Food Security themes.', 'تحلل إدارة اقتصاديات المياه والزراعة اقتصاديات إمدادات المياه وإدارة الطلب والإنتاج الغذائي والتجارة. وتعد دراسات التكلفة والعائد لمبادرات البرنامج وخيارات التعرفة والاستثمار، وتتابع المؤشرات الاقتصادية التي تؤطر محوري الأمن المائي والأمن الغذائي والزراعة.', '01M4D6BHEV9G5W4Q3XS5WPTZNG', '01M4D6CAGXNZAHAF8RXASHE207', '2026-10-08T07:23:58.764Z', '2026-10-08T07:24:25.506Z', 'Leads the water security theme of the NES: demand and supply balance, desalination and wastewater reuse, and the water policy pipeline with MEWA, SWA and NWC.', 'تقود محور الأمن المائي في الاستراتيجية الوطنية للبيئة: توازن العرض والطلب وتحلية المياه وإعادة استخدام المياه المعالجة وخط سياسات المياه مع وزارة البيئة والمياه والزراعة والهيئة السعودية للمياه وشركة المياه الوطنية.', NULL, 'department', 'Supports the water security theme: demand and supply balance, resource efficiency and coordination with water sector entities.', 'تدعم محور الأمن المائي: التوازن بين الطلب والإمداد وكفاءة الموارد والتنسيق مع جهات قطاع المياه.', '', '', '2026-01-01T00:00:00.000Z', 'Khalid Al-Salem', 'خالد السالم', 'Department Director', 'مدير الإدارة', 12, 1),
('01M4D6BGEM49D56VJH4VTHV705', 'AFD', 'Agriculture and Food Security', 'إدارة الأمن الغذائي والزراعة', 'The Biodiversity, Land and Community Programmes Department coordinates the programmes that protect habitats, restore degraded land and engage communities, working with the National Center for Wildlife and the National Center for Vegetation Cover Development and Combating Desertification.', 'تنسق إدارة برامج التنوع الأحيائي والأراضي والمجتمع البرامج التي تحمي الموائل وتعيد تأهيل الأراضي المتدهورة وتشرك المجتمعات، بالتعاون مع المركز الوطني للحياة الفطرية والمركز الوطني لتنمية الغطاء النباتي ومكافحة التصحر.', '01M4D6BHF37BQ4PDMG2KHFXHXX', '01M4D6CAGXNZAHAF8RXASHE207', '2026-10-08T07:23:58.764Z', '2026-10-08T07:24:25.506Z', 'Leads the agriculture and food security theme: sustainable farming, agricultural water use, food supply resilience, and alignment with GFSA and FAO.', 'تقود محور الأمن الغذائي والزراعة: الزراعة المستدامة واستخدام المياه الزراعية ومرونة إمدادات الغذاء والمواءمة مع الهيئة العامة للأمن الغذائي ومنظمة الفاو.', NULL, 'department', 'Supports the agriculture and food security theme: sustainable production, agricultural water use and food supply resilience.', 'تدعم محور الأمن الغذائي والزراعة: الإنتاج المستدام واستخدام المياه الزراعية ومرونة الإمداد الغذائي.', '', '', '2026-01-01T00:00:00.000Z', 'Maha Al-Yami', 'مها اليامي', 'Department Director', 'مدير الإدارة', 13, 1),
('01M4D6BGENG69HJJCBAM584JAY', 'FRS', 'Foresight and Risk', 'إدارة الاستشراف والمخاطر', 'The Climate, Foresight and Risk Department scans emerging climate, water and land risks, builds scenarios for the programme and maintains the programme risk register. It supports the Saudi Green Initiative and Middle East Green Initiative reporting lines.', 'ترصد إدارة المناخ والاستشراف والمخاطر المخاطر الناشئة في المناخ والمياه والأراضي، وتبني سيناريوهات للبرنامج، وتدير سجل مخاطر البرنامج. وتدعم مسارات إعداد التقارير لمبادرة السعودية الخضراء ومبادرة الشرق الأوسط الأخضر.', '01M4D6BHF44SK2EWVZFR2XDBGM', '01M4D6CAGXNZAHAF8RXASHE207', '2026-10-08T07:23:58.764Z', '2026-10-08T07:24:25.506Z', 'Runs horizon scanning, the signals pipeline, environmental risk registers, and futures work that feeds the mid-term review.', 'تدير استشراف الأفق وخط الإشارات وسجلات المخاطر البيئية وأعمال المستقبلات التي تغذي مراجعة منتصف المدة.', NULL, 'department', 'Scans the horizon for environmental risks and opportunities and prepares the quarterly strategic risk briefing for leadership.', 'تمسح الأفق بحثاً عن المخاطر والفرص البيئية وتعد إحاطة المخاطر الاستراتيجية الربع سنوية للقيادة.', '', '', '2026-01-01T00:00:00.000Z', 'Turki Al-Anazi', 'تركي العنزي', 'Department Director', 'مدير الإدارة', 9, 1),
('01M4D6BGEN0X0HZVKB2P6E6678', 'PMD', 'Programme Monitoring', 'إدارة متابعة البرنامج', 'The Performance Monitoring and Compliance Department tracks delivery of programme initiatives and projects against plan, evaluates results and follows regulatory compliance and enforcement indicators published by the competent regulators.', 'تتابع إدارة متابعة الأداء والامتثال تنفيذ مبادرات البرنامج ومشاريعه مقارنة بالخطة، وتقيّم النتائج، وتتابع مؤشرات الامتثال التنظيمي والإنفاذ التي تنشرها الجهات التنظيمية المختصة.', '01M4D6BHF6AGFKMMP55YD3AM5K', '01M4D6CAGXNZAHAF8RXASHE207', '2026-10-08T07:23:58.764Z', '2026-10-08T07:24:25.505Z', 'Owns the NES results framework: KPI collection, status updates, delivery reviews, and the evaluation calendar.', 'تملك إطار نتائج الاستراتيجية الوطنية للبيئة: جمع مؤشرات الأداء وتحديثات الحالة ومراجعات الإنجاز وتقويم التقييم.', NULL, 'department', 'Runs the monitoring framework and the reporting cycle for the National Environment Strategy, and consolidates progress from entities into the delivery dashboard.', 'تدير إطار المتابعة ودورة إعداد التقارير للاستراتيجية الوطنية للبيئة، وتجمع تقدم الجهات في لوحة متابعة التنفيذ.', '', '', '2026-01-01T00:00:00.000Z', 'Saud Al-Otaibi', 'سعود العتيبي', 'Department Director', 'مدير الإدارة', 5, 1),
('01M4D6BGEN9QDGX3095WSWMVDJ', 'OPD', 'Office of the Programme Director', 'مكتب مدير البرنامج', 'The Office of the Programme Director provides executive support to the Programme Director, runs communications and legal advice for the Programme Office, and coordinates relations with MEWA and the delivery entities.', 'يقدم مكتب مدير البرنامج الدعم التنفيذي لمدير البرنامج، ويتولى الاتصال المؤسسي والمشورة القانونية لمكتب البرنامج، وينسق العلاقة مع وزارة البيئة والمياه والزراعة والجهات المنفذة.', '01M4D6BHF6S74N94EN6YKC3CPH', NULL, '2026-10-08T07:23:58.764Z', '2026-10-08T07:24:25.501Z', 'Supports the Programme Director: steering committee coordination, entity relations, and the Office''s decision pipeline.', 'يساند مدير البرنامج: التنسيق مع اللجنة التوجيهية وعلاقات الجهات وخط قرارات المكتب.', NULL, 'office', 'Leads the Office, chairs its executive committee and answers to the Programme Steering Committee for delivery of the National Environment Strategy. Sets priorities across sectors and represents the Office with national entities.', 'يقود المكتب ويرأس لجنته التنفيذية ويرفع إلى اللجنة التوجيهية للبرنامج عن تنفيذ الاستراتيجية الوطنية للبيئة. يحدد الأولويات بين القطاعات ويمثل المكتب لدى الجهات الوطنية.', '', '', '2026-01-01T00:00:00.000Z', 'Faisal Al-Harbi', 'فيصل الحربي', 'Head of Office', 'رئيس المكتب', 1, 1),
('01M4D6BGENB6WPFZF0BJRG1PX3', 'DIG', 'Digital', 'إدارة الرقمنة', 'The Information Technology Department builds and maintains the technology platform of the Programme Office, including the EnviroAI knowledge system, identity, security and the analytics environment.', 'تبني إدارة تقنية المعلومات المنصة التقنية لمكتب البرنامج وتحافظ عليها، بما في ذلك منظومة المعرفة EnviroAI والهوية والأمن وبيئة التحليلات.', '01M4D6BHF8ZTSM8WQ4KK84M1E1', '01M4D6CAH5H14KDXZP670RRKHD', '2026-10-08T07:23:58.764Z', '2026-10-08T07:24:25.509Z', 'Operates EnviroAI and the Office''s digital platforms, integrations, and information security posture.', 'تشغل EnviroAI والمنصات الرقمية للمكتب وتكاملاتها ووضعها في أمن المعلومات.', NULL, 'department', 'Runs the Office''s digital workplace, infrastructure, information security operations and business continuity.', 'تدير بيئة العمل الرقمية والبنية التحتية وعمليات أمن المعلومات واستمرارية الأعمال في المكتب.', '', '', '2026-01-01T00:00:00.000Z', 'Osama Al-Rumaih', 'أسامة الرميح', 'Department Director', 'مدير الإدارة', 29, 1),
('01M4D6CAGXNZAHAF8RXASHE207', 'SPS', 'Strategy and Performance Sector', 'قطاع الاستراتيجية والأداء', NULL, NULL, NULL, '01M4D6BGEN9QDGX3095WSWMVDJ', '2026-10-08T07:24:25.501Z', '2026-10-08T07:24:25.501Z', NULL, NULL, NULL, 'sector', 'Oversees strategy development, planning standards, programme monitoring and evaluation, and the theme teams for water, agriculture, climate, biodiversity, waste and air quality.', 'يشرف على تطوير الاستراتيجية ومعايير التخطيط ومتابعة البرنامج وتقييمه وفرق المحاور للمياه والزراعة والمناخ والتنوع الأحيائي والنفايات وجودة الهواء.', '', '', '2026-01-01T00:00:00.000Z', 'Noura Al-Qahtani', 'نورة القحطاني', 'Sector Head', 'رئيس القطاع', 2, 1),
('01M4D6CAGYP0HZ6XYMWHB2BYZT', 'PQS', 'Planning Quality and Standards', 'إدارة جودة الخطط والمعايير', NULL, NULL, NULL, '01M4D6CAGXNZAHAF8RXASHE207', '2026-10-08T07:24:25.502Z', '2026-10-08T07:24:25.502Z', NULL, NULL, NULL, 'department', 'Issues the results framework manual and templates, and reviews the quality of sector and entity strategies against them.', 'تصدر دليل إطار النتائج ونماذجه، وتراجع جودة استراتيجيات القطاعات والجهات وفقاً له.', '', '', '2026-01-01T00:00:00.000Z', 'Reem Al-Shehri', 'ريم الشهري', 'Department Director', 'مدير الإدارة', 4, 1),
